namespace sv_a65dc9103635484990913e37ce059efe;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_a65dc9103635484990913e37ce059efe.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="board-container">
    @if (isLoading)
    {
        <div class="board-loading">Loading tasks...</div>
    }
    else if (errorMessage is not null)
    {
        <div class="board-error">
            <p>@errorMessage</p>
            <button @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStats Total="allTasks.Count"
                    ToDoCount="GetTasksByStatus("To Do").Count"
                    InProgressCount="GetTasksByStatus("In Progress").Count"
                    DoneCount="GetTasksByStatus("Done").Count"
                    OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

        <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="HandleSearchChanged" />

        <div class="kanban-board">
            <KanbanColumn ColumnName="To Do"
                          Status="To Do"
                          Tasks="GetFilteredTasksByStatus("To Do")"
                          CanMoveLeft="false"
                          CanMoveRight="true"
                          OnMoveTask="HandleMoveTask"
                          OnAddTask="HandleAddTask" />

            <KanbanColumn ColumnName="In Progress"
                          Status="In Progress"
                          Tasks="GetFilteredTasksByStatus("In Progress")"
                          CanMoveLeft="true"
                          CanMoveRight="true"
                          OnMoveTask="HandleMoveTask"
                          OnAddTask="HandleAddTask" />

            <KanbanColumn ColumnName="Done"
                          Status="Done"
                          Tasks="GetFilteredTasksByStatus("Done")"
                          CanMoveLeft="true"
                          CanMoveRight="false"
                          OnMoveTask="HandleMoveTask"
                          OnAddTask="HandleAddTask" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksByStatus(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksByStatus(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchTerm) ||
                        t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task HandleMoveTask((int TaskId, MoveDirection Direction) args)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == args.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        var newIndex = args.Direction == MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Statuses.Length) return;

        var newStatus = Statuses[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Update local state
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Status, NewTaskModel Model) args)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(
                args.Model.Title,
                args.Model.Assignee,
                args.Model.Priority,
                args.Model.DueDate);
            // The service returns the task; ensure it has the correct status
            allTasks.Add(newTask with { Status = args.Status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem;
}

.board-loading,
.board-error {
    text-align: center;
    padding: 2rem;
    font-size: 1.1rem;
}

.board-error {
    color: #dc3545;
}

.board-error button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    cursor: pointer;
}

/* Stats Bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: bold;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

/* Kanban Board */
.kanban-board {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
}

/* Column */
.kanban-column {
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    min-height: 400px;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid #dee2e6;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    background: #6c757d;
    color: white;
    border-radius: 50%;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    margin-top: 1rem;
}

